example_programs.heapify_pop:
from collections import defaultdict
import heapq

def solve(nums, k):
    count = defaultdict(int)
    for num in nums:
        count[num] += 1
    heap = []
    for num, freq in count.items():
        heapq.heappush(heap, (num, freq))
    while heap:
        num, freq = heapq.heappop(heap)
        if k <= freq:
            return num
        k -= freq
    return None

