def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check for negative weight cycles (if any path can be shortened)
    for u in range(n):
        if dist[u] != float('inf'):
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    # If there's a negative cycle that is reachable from s
                    if dist[u] != float('inf'):
                        # Check if t is reachable from u (we can't just assume)
                        # We need to check if t is reachable from u
                        # To do that, we can do BFS from u to t in the original graph
                        visited = set()
                        queue = deque()
                        queue.append(u)
                        visited.add(u)
                        while queue:
                            node = queue.popleft()
                            if node == t:
                                break
                            for v, _ in adj[node]:
                                if v not in visited:
                                    visited.add(v)
                                    queue.append(v)
                        if t in visited:
                            return -1

    return dist[t] if dist[t] != float('inf') else -1

